build.js
import fs from 'fs';
import path from 'path';
import archiver from 'archiver';
import puppeteer from 'puppeteer';
import sharp from 'sharp';

const HTML = 'focus-reset.html';
const IOS_SVG = 'focus-reset-ios.svg';
const ANDROID_SVG = 'focus-reset-android.svg';

const OUT_LETTER = 'focus-reset_letter.pdf';
const OUT_A4 = 'focus-reset_a4.pdf';
const OUT_IOS = 'focus-reset_ios_1170x2532.png';
const OUT_ANDROID = 'focus-reset_android_1080x2400.png';
const OUT_ZIP = 'focus-reset_assets_v1.zip';

// Inline remote QR in SVGs to avoid network hiccups during rasterization
async function inlineQR(svgPath) {
  const svg = await fs.promises.readFile(svgPath, 'utf8');
  const match = svg.match(/<image[^>]*href="([^"]+)"[^>]*>/i);
  if (!match) return svg;
  const url = match[1];
  const res = await fetch(url); // Node 18+ has global fetch
  if (!res.ok) throw new Error(`Failed to fetch QR: ${url} (${res.status})`);
  const buf = Buffer.from(await res.arrayBuffer());
  const isSvg = url.includes('format=svg') || buf.slice(0, 5).toString().includes('<svg');
  const mime = isSvg ? 'image/svg+xml' : 'image/png';
  const dataUri = `data:${mime};base64,` + buf.toString('base64');
  return svg.replace(url, dataUri);
}

async function makePDFs() {
  const browser = await puppeteer.launch({ headless: 'new' });
  try {
    const page = await browser.newPage();
    const fileUrl = 'file://' + path.resolve(HTML);
    await page.goto(fileUrl, { waitUntil: 'networkidle0' });
    // Ensure Inter is fully loaded before printing
    await page.evaluate(() => (document.fonts ? document.fonts.ready.then(() => true) : true));
    // Set PDF Title metadata
    await page.evaluate(() => { document.title = '2‑minute focus reset'; });

    const common = {
      printBackground: true,
      margin: { top: '1in', right: '1in', bottom: '1in', left: '1in' }
    };

    await page.pdf({ ...common, path: OUT_LETTER, format: 'Letter' });
    await page.pdf({ ...common, path: OUT_A4, format: 'A4' });
  } finally {
    await browser.close();
  }
}

async function makePNGs() {
  // iOS PNG (1170×2532), inline QR first
  const iosSVG = await inlineQR(IOS_SVG);
  await sharp(Buffer.from(iosSVG), { density: 326 })
    .resize(1170, 2532)
    .png({ compressionLevel: 9, progressive: false })
    .toFile(OUT_IOS);

  // Android PNG (1080×2400), inline QR first
  const androidSVG = await inlineQR(ANDROID_SVG);
  await sharp(Buffer.from(androidSVG), { density: 320 })
    .resize(1080, 2400)
    .png({ compressionLevel: 9, progressive: false })
    .toFile(OUT_ANDROID);
}

async function makeZip() {
  const archive = archiver('zip', { zlib: { level: 9 } });
  const stream = fs.createWriteStream(OUT_ZIP);
  return new Promise((resolve, reject) => {
    archive.on('error', reject);
    stream.on('close', resolve);
    archive.pipe(stream);
    [OUT_LETTER, OUT_A4, OUT_IOS, OUT_ANDROID].forEach(f => archive.file(f, { name: f }));
    archive.finalize();
  });
}

