2) Add i18n/render.js
import fs from 'fs/promises';
import path from 'path';

const TEMPLATES = [
  { in: 'focus-reset.html.tmpl', out: 'focus-reset.html' },
  { in: 'focus-reset-ios.svg.tmpl', out: 'focus-reset-ios.svg' },
  { in: 'focus-reset-android.svg.tmpl', out: 'focus-reset-android.svg' }
];

function render(template, data) {
  // Minimal Mustache-like renderer: supports {{key}} and {{#list}}...{{/list}}
  let out = template;
  // Lists
  out = out.replace(/{{#(\w+)}}([\s\S]*?){{\/\1}}/g, (_, key, block) => {
    const arr = data[key] || [];
    return arr.map(item => block.replace(/{{\.}}/g, String(item))).join('');
  });
  // Scalars
  out = out.replace(/{{(\w+)}}/g, (_, key) => (data[key] ?? ''));
  return out;
}

async function main() {
  const locales = (process.env.LOCALES || 'en').split(',').map(s => s.trim()).filter(Boolean);
  for (const locale of locales) {
    const src = JSON.parse(await fs.readFile(path.join('i18n', `strings.${locale}.json`), 'utf8'));
    for (const t of TEMPLATES) {
      const tmpl = await fs.readFile(t.in, 'utf8');
      const out = render(tmpl, src);
      const outName = locales.length > 1 ? t.out.replace('.', `.${locale}.`) : t.out;
      await fs.writeFile(outName, out, 'utf8');
    }
  }
}

main().catch(err => { console.error(err); process.exit(1); });

