import fs from 'fs/promises';
import path from 'path';

const TEMPLATES = [
  { in: 'focus-reset.html.tmpl', out: 'focus-reset.html' },
  { in: 'focus-reset-ios.svg.tmpl', out: 'focus-reset-ios.svg' },
  { in: 'focus-reset-android.svg.tmpl', out: 'focus-reset-android.svg' }
];

// Basic Mustache-like renderer: {{key}}, {{#list}}..{{/list}}; supports objects in lists via {{prop}}
function render(template, data) {
  let out = template;

  // Section/array loops
  out = out.replace(/{{#(\w+)}}([\s\S]*?){{\/\1}}/g, (_, key, block) => {
    const arr = data[key] || [];
    return arr.map(item => {
      if (typeof item === 'object') {
        return block.replace(/{{(\w+)}}/g, (__, k) => (k === '.' ? String(item) : (item[k] ?? '')));
      }
      return block.replace(/{{\w+}}/g, m => (m === '{{.}}' ? String(item) : ''));
    }).join('');
  });

  // Scalars
  out = out.replace(/{{(\w+)}}/g, (_, key) => (data[key] ?? ''));
  return out;
}

function svgVars(device, dir) {
  if (device === 'ios') {
    // Canvas 1170×2532, margin 100, QR 360
    return dir === 'rtl'
      ? { text_x: 1070, text_anchor: 'end', qr_x: 100 }
      : { text_x: 100,  text_anchor: 'start', qr_x: 710 };
  }
  // Android: 1080×2400, margin 88, QR 340
  return dir === 'rtl'
    ? { text_x: 992, text_anchor: 'end', qr_x: 88 }
    : { text_x: 88,  text_anchor: 'start', qr_x: 652 };
}

function lockStepY(device) {
  // Fixed Y positions matching your originals
  return device === 'ios'
    ? [660, 740, 820, 900]
    : [610, 690, 770, 850];
}

const QR_IOS = 'https://api.qrserver.com/v1/create-qr-code/?size=360x360&format=svg&color=FFFFFF&data=https%3A%2F%2Ftimer.onlineclock.net%2F%3Ftime%3D10%3A00';
const QR_ANDROID = 'https://api.qrserver.com/v1/create-qr-code/?size=340x340&format=svg&color=FFFFFF&data=https%3A%2F%2Ftimer.onlineclock.net%2F%3Ftime%3D10%3A00';

async function main() {
  const locales = (process.env.LOCALES || 'en').split(',').map(s => s.trim()).filter(Boolean);
  const theme = process.env.THEME || 'bw'; // 'bw' or 'accent'

  for (const locale of locales) {
    const src = JSON.parse(await fs.readFile(path.join('i18n', `strings.${locale}.json`), 'utf8'));
    const data = {
      ...src,
      accent: theme === 'accent' ? '#2563EB' : (src.accent || '#111111'),
      // For SVG: expand lock_steps with y positions
      lock_steps: (src.lock_steps || []).map((text, i) => ({ text, y: lockStepY('ios')[i] }))
    };

    // iOS SVG
    const iosTmpl = await fs.readFile('focus-reset-ios.svg.tmpl', 'utf8');
    const iosVars = svgVars('ios', src.dir || 'ltr');
    const iosOut = render(iosTmpl, { ...data, ...iosVars, qr_href: QR_IOS });
    const iosOutName = locales.length > 1 || theme !== 'bw' ? `focus-reset-ios.${locale}.${theme}.svg` : 'focus-reset-ios.svg';
    await fs.writeFile(iosOutName, iosOut, 'utf8');

    // Android SVG
    const andTmpl = await fs.readFile('focus-reset-android.svg.tmpl', 'utf8');
    const andVars = svgVars('android', src.dir || 'ltr');
    // Rebuild lock_steps with Android Y
    const andSteps = (src.lock_steps || []).map((text, i) => ({ text, y: lockStepY('android')[i] }));
    const andOut = render(andTmpl, { ...data, ...andVars, lock_steps: andSteps, qr_href: QR_ANDROID });
    const andOutName = locales.length > 1 || theme !== 'bw' ? `focus-reset-android.${locale}.${theme}.svg` : 'focus-reset-android.svg';
    await fs.writeFile(andOutName, andOut, 'utf8');

    // HTML
    const htmlTmpl = await fs.readFile('focus-reset.html.tmpl', 'utf8');
    const htmlOut = render(htmlTmpl, data);
    const htmlOutName = locales.length > 1 || theme !== 'bw' ? `focus-reset.${locale}.${theme}.html` : 'focus-reset.html';
    await fs.writeFile(htmlOutName, htmlOut, 'utf8');
  }
}

main().catch(err => { console.error(err); process.exit(1); });

