Awesome—integrations look great. To make multi-locale/multi-theme builds zero-rename, here’s a drop-in build.js that accepts explicit inputs and auto-suffixes outputs. Plus a CI matrix that uses it directly.

Updated build.js (CLI args: --html, --ios, --android, --suffix, --ci)
- Produces outputs with your chosen suffix, e.g., _es_bw
- Keeps all previous hardening (fonts ready, QR inline, CI flags, checksums, zip)

import fs from 'fs';
import fsp from 'fs/promises';
import path from 'path';
import archiver from 'archiver';
import puppeteer from 'puppeteer';
import sharp from 'sharp';
import crypto from 'crypto';

function arg(name, def = undefined) {
  const i = process.argv.findIndex(a => a === `--${name}`);
  return i >= 0 ? (process.argv[i + 1] || '') : def;
}
const HTML_IN = arg('html', 'focus-reset.html');
const IOS_SVG_IN = arg('ios', 'focus-reset-ios.svg');
const ANDROID_SVG_IN = arg('android', 'focus-reset-android.svg');
const SUFFIX = arg('suffix', '').replace(/[^a-z0-9_\-\.]/gi, '');
const isCI = process.argv.includes('--ci') || process.env.CI === 'true';

const OUT_LETTER = `focus-reset_letter${SUFFIX ? '_' + SUFFIX : ''}.pdf`;
const OUT_A4 = `focus-reset_a4${SUFFIX ? '_' + SUFFIX : ''}.pdf`;
const OUT_IOS = `focus-reset_ios_1170x2532${SUFFIX ? '_' + SUFFIX : ''}.png`;
const OUT_ANDROID = `focus-reset_android_1080x2400${SUFFIX ? '_' + SUFFIX : ''}.png`;
const OUT_ZIP = `focus-reset_assets_v1${SUFFIX ? '_' + SUFFIX : ''}.zip`;
const OUT_SUMS = `checksums${SUFFIX ? '_' + SUFFIX : ''}.txt`;

async function fetchWithRetry(url, n = 3) {
  let lastErr;
  for (let i = 0; i < n; i++) {
    try {
      const res = await fetch(url);
      if (res && res.ok) return res;
      lastErr = new Error(`HTTP ${res?.status} ${res?.statusText}`);
    } catch (e) { lastErr = e; }
    await new Promise(r => setTimeout(r, 300 * (i + 1)));
  }
  throw new Error(`QR fetch failed after retries: ${url} (${lastErr})`);
}

async function inlineQR(svgPath) {
  const svg = await fsp.readFile(svgPath, 'utf8');
  const match = svg.match(/<image[^>]*href="([^"]+)"[^>]*>/i);
  if (!match) return svg;
  const url = match[1];
  const res = await fetchWithRetry(url);
  const buf = Buffer.from(await res.arrayBuffer());
  const isSvg = url.includes('format=svg') || buf.slice(0, 100).toString().includes('<svg');
  const mime = isSvg ? 'image/svg+xml' : 'image/png';
  const dataUri = `data:${mime};base64,` + buf.toString('base64');
  return svg.replace(url, dataUri);
}

async function makePDFs() {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: isCI ? ['--no-sandbox', '--disable-setuid-sandbox'] : []
  });
  try {
    const page = await browser.newPage();
    const fileUrl = 'file://' + path.resolve(HTML_IN);
    await page.goto(fileUrl, { waitUntil: 'networkidle0' });
    await page.evaluate(() => (document.fonts ? document.fonts.ready.then(() => true) : true));
    await page.evaluate(() => { document.title = '2‑minute focus reset'; });
    const common = { printBackground: true, margin: { top: '1in', right: '1in', bottom: '1in', left: '1in' } };
    await page.pdf({ ...common, path: OUT_LETTER, format: 'Letter' });
    await page.pdf({ ...common, path: OUT_A4, format: 'A4' });
  } finally {
    await browser.close();
  }
}

async function makePNGs() {
  const iosSVG = await inlineQR(IOS_SVG_IN);
  await sharp(Buffer.from(iosSVG), { density: 326 })
    .resize(1170, 2532)
    .png({ compressionLevel: 9, progressive: false })
    .toFile(OUT_IOS);

  const androidSVG = await inlineQR(ANDROID_SVG_IN);
  await sharp(Buffer.from(androidSVG), { density: 320 })
    .resize(1080, 2400)
    .png({ compressionLevel: 9, progressive: false })
    .toFile(OUT_ANDROID);
}

async function makeZip() {
  const archive = archiver('zip', { zlib: { level: 9 } });
  const stream = fs.createWriteStream(OUT_ZIP);
  return new Promise((resolve, reject) => {
    archive.on('error', reject);
    stream.on('close', resolve);
    archive.pipe(stream);
    [OUT_LETTER, OUT_A4, OUT_IOS, OUT_ANDROID].forEach(f => archive.file(f, { name: f }));
    archive.finalize();
  });
}

function sha256FileSync(filePath) {
  const hash = crypto.createHash('sha256');
  hash.update(fs.readFileSync(filePath));
  return hash.digest('hex');
}

async function writeChecksums() {
  const files = [OUT_LETTER, OUT_A4, OUT_IOS, OUT_ANDROID, OUT_ZIP].filter(f => fs.existsSync(f));
  const lines = files.map(f => `${sha256FileSync(f)}  ${f}\n`);
  await fsp.writeFile(OUT_SUMS, lines.join(''), 'utf8');
  console.log('Checksums written to', OUT_SUMS);
}

(async () => {
  await makePDFs();
  await makePNGs();
  await makeZip();
  await writeChecksums();
  console.log('Done:\n -', OUT_LETTER, '\n -', OUT_A4, '\n -', OUT_IOS, '\n -', OUT_ANDROID, '\n -', OUT_ZIP, '\n -', OUT_SUMS);
})().catch(err => { console.error(err); process.exit(1); });

