    },
    {
        "Venue": "Moules & Co",
        "Source URL": "https://moulesandco.pt/#contactos",
        "Best via": "",
        "Notes": "Restaurant contact"
    },
    {
        "Venue": "Sea Me — Peixaria Moderna",
        "Source URL": "https://peixariamoderna.com/contactos/",
        "Best via": "",
