    },
    {
        "Venue": "Lisbon Street Art Tours",
        "Source URL": "https://lisbonstreetarttours.com/contact/",
        "Best via": "",
        "Notes": "Tour contact (WhatsApp often listed)"
    },
    {
        "Venue": "Mosteiro dos Jerónimos (official)",
        "Source URL": "https://patrimoniocultural.gov.pt/monuments/mosteiro-dos-jeronimos/",
        "Best via": "Best via form if present",
        "Notes": "Official info/tickets; phone may be generic to the directorate"
    },
    {
        "Venue": "MAAT",
        "Source URL": "https://www.maat.pt/en/plan-your-visit",
        "Best via": "Best via form",
        "Notes": "Visitor info/contact"
    },
    {
