        "Source URL": "https://www.mnazulejo.gov.pt/en/plan-your-visit/",
        "Best via": "",
        "Notes": "Visitor info/contact"
    },
    {
        "Venue": "Parques de Sintra (Pena)",
        "Source URL": "https://www.parquesdesintra.pt/en/contacts/",
        "Best via": "Best via form",
        "Notes": "Parks & palaces contact"
    },
    {
        "Venue": "Quinta da Regaleira",
        "Source URL": "https://www.quintadaregaleira.pt/en/contacts/",
        "Best via": "",
        "Notes": "Official contacts"
    }
]

HEADERS = ["Venue","Reservations Phone","+WhatsApp","General Phone","Best via","Source URL","Notes"]

# Basic Portuguese phone patterns (robust but conservative)
PHONE_REGEX = re.compile(r'(\+351[\s\-\.\(\)\d]{6,15}|\b2\d{8}\b|\b9\d{8}\b)')
WHATSAPP_HINTS = re.compile(r'whats\s*app|whatsapp', re.I)
RESERVATION_HINTS = re.compile(r'reserv|booking|book|mesa|reservation', re.I)

def normalize_pt(num_raw):
    clean = re.sub(r'[^\d+]', '', num_raw)
    # If already +351, parse/format
    try:
        if not clean.startswith('+'):
            # Local PT numbers: e.g., 21xxxxxxx (Lisbon), 91/92/93/96 mobiles
            if re.match(r'^[29]\d{8}$', clean):
                clean = '+351' + clean
            else:
                return ""
        parsed = phonenumbers.parse(clean, None)
        if phonenumbers.is_possible_number(parsed) and phonenumbers.is_valid_number(parsed):
            return phonenumbers.format_number(parsed, phonenumbers.PhoneNumberFormat.E164)
    except Exception:
        pass
    return ""

def extract_numbers(html):
    soup = BeautifulSoup(html, "html.parser")
    text = soup.get_text(" ", strip=True)
    # Look for numbers and surrounding context
    matches = []
    for m in PHONE_REGEX.finditer(text):
        start = max(0, m.start()-40); end = min(len(text), m.end()+40)
        context = text[start:end]
        matches.append((m.group(), context))
    # Classify
    reservations = []
    general = []
    whatsapp = []
    for raw, ctx in matches:
        norm = normalize_pt(raw)
        if not norm: 
            continue
        if WHATSAPP_HINTS.search(ctx):
            if norm not in whatsapp: whatsapp.append(norm)
        if RESERVATION_HINTS.search(ctx):
            if norm not in reservations: reservations.append(norm)
        else:
            if norm not in general: general.append(norm)
    return reservations, whatsapp, general

def main():
    out_rows = []
    for src in SOURCES:
        url = src["Source URL"]
        try:
            r = requests.get(url, timeout=15)
            r.raise_for_status()
            reservations, whatsapp, general = extract_numbers(r.text)
        except Exception:
            reservations, whatsapp, general = [], [], []
        # Fallback: if no reservations but some general, keep general
        row = {
            "Venue": src["Venue"],
            "Reservations Phone": "; ".join(reservations),
            "+WhatsApp": "; ".join(whatsapp),
            "General Phone": "; ".join(general),
            "Best via": src.get("Best via",""),
            "Source URL": url,
            "Notes": src.get("Notes","")
        }
        out_rows.append(row)

    with open("lisbon-2026-contacts-verified.csv", "w", newline="", encoding="utf-8") as f:
        w = csv.DictWriter(f, fieldnames=HEADERS)
        w.writeheader()
        for row in out_rows:
            w.writerow(row)

if __name__ == "__main__":
    main()

What to expect
- Most restaurants and the hotel should return a reservations number; some will list WhatsApp.
- Jerónimos/MAAT/Parques de Sintra may prefer forms; the script will capture any numbers on their pages, but “Best via form” remains in the CSV where applicable.

Optional manual pass (1–2 minutes)
- If a row comes back blank, open the Source URL and copy the posted Reservations/WhatsApp number into the CSV. Keep both Reservations and General if they differ.
- If a venue’s page lists separate lines (reservations vs events), put reservations first; separate multiples with “; ”.

